// Enhancements only: every case, metric, and navigation link is pre-rendered HTML.
const root=document.documentElement;
const systemReduced=matchMedia('(prefers-reduced-motion: reduce)');
const reduced=()=>systemReduced.matches||root.dataset.motion==='off';
const duration=ms=>reduced()?0:ms;
function syncPreferences(){document.querySelectorAll('.theme-toggle b').forEach(b=>b.textContent=root.dataset.theme==='ink'?'Ink':'Paper');document.querySelectorAll('.motion-toggle b').forEach(b=>b.textContent=reduced()?'Off':'On');document.querySelector('meta[name="theme-color"]').content=root.dataset.theme==='ink'?'#20252c':'#eeeae2'}
syncPreferences();systemReduced.addEventListener('change',syncPreferences);
document.querySelectorAll('.theme-toggle').forEach(button=>button.addEventListener('click',()=>{root.dataset.theme=root.dataset.theme==='ink'?'paper':'ink';try{localStorage.setItem('rr-casebook-theme',root.dataset.theme)}catch{}syncPreferences()}));
document.querySelectorAll('.motion-toggle').forEach(button=>button.addEventListener('click',()=>{root.dataset.motion=root.dataset.motion==='off'?'on':'off';try{localStorage.setItem('rr-motion',root.dataset.motion)}catch{}syncPreferences();toast(systemReduced.matches?'Reduced motion follows your device setting.':`Motion ${reduced()?'off':'on'}.`)}));
function clock(){const t=document.querySelector('#local-time');if(t)t.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' WIB'}clock();setInterval(clock,60000);
let toastTimer;
function toast(message){const t=document.querySelector('.toast'),host=document.querySelector('dialog[open]')||document.body;host.append(t);t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message)}catch{toast('Please select and copy the text. Clipboard access is unavailable.')}}
document.querySelectorAll('.copy-email').forEach(b=>b.addEventListener('click',()=>copy('rifaldiriqhia@gmail.com','Email copied.')));
const openers=new WeakMap(),closing=new WeakSet();
function open(dialog,opener){openers.set(dialog,opener||document.activeElement);dialog.showModal();dialog.scrollTop=0;document.body.classList.add('modal-open');dialog.classList.add('opening');setTimeout(()=>dialog.classList.remove('opening'),duration(320))}
function close(dialog,after){if(closing.has(dialog))return;closing.add(dialog);dialog.classList.add('closing');setTimeout(()=>{document.body.append(document.querySelector('.toast'));dialog.close();dialog.classList.remove('closing');closing.delete(dialog);document.body.classList.remove('modal-open');openers.get(dialog)?.focus({preventScroll:true});after?.()},duration(200))}
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('[data-close]').addEventListener('click',()=>close(dialog));dialog.addEventListener('cancel',event=>{event.preventDefault();close(dialog)});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close(dialog)})});
const menu=document.querySelector('#menu-dialog');document.querySelector('.menu-open').addEventListener('click',event=>open(menu,event.currentTarget));menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',event=>{event.preventDefault();close(menu,()=>{location.href=a.href})}));

// Evidence data is published from the case's validated content, never mock records.
const records=JSON.parse(document.querySelector('#evidence-data').textContent);
const gallery=records.flatMap((record,index)=>(record.images||[]).map((image,imageIndex)=>({record,image,index,imageIndex})));
const viewer=document.querySelector('#evidence-viewer');const stage=viewer.querySelector('.viewer-stage');const viewImage=stage.querySelector('img');let current=0;
function showImage(index){if(!gallery.length)return;current=(index+gallery.length)%gallery.length;const {record,image,imageIndex}=gallery[current];stage.classList.remove('zoomed');viewer.querySelector('[data-zoom]').textContent='Zoom in';viewer.querySelector('[data-zoom]').setAttribute('aria-pressed','false');stage.querySelector('.viewer-error').hidden=true;viewImage.hidden=false;viewImage.alt=image.alt||record.title;viewImage.src=image.src;document.querySelector('#viewer-title').textContent=`${record.id} / ${record.title}`;viewer.querySelector('.viewer-caption').textContent=[record.source,record.date,image.caption||record.caption||record.description,record.type==='comparison'?(imageIndex===0?'Before':'After'):'',record.redacted?'Sensitive information redacted':''].filter(Boolean).join(' · ');viewer.querySelector('.viewer-count').textContent=`${current+1} / ${gallery.length}`;viewer.querySelector('.viewer-original').href=image.src;viewer.querySelector('[data-prev]').disabled=gallery.length<2;viewer.querySelector('[data-next]').disabled=gallery.length<2}
viewImage.addEventListener('error',()=>{viewImage.hidden=true;stage.querySelector('.viewer-error').hidden=false});
document.querySelectorAll('[data-evidence]').forEach(button=>button.addEventListener('click',()=>{const idx=gallery.findIndex(x=>x.index===Number(button.dataset.evidence)&&x.imageIndex===Number(button.dataset.image));if(idx<0)return;showImage(idx);open(viewer,button)}));
viewer.querySelector('[data-prev]').addEventListener('click',()=>showImage(current-1));viewer.querySelector('[data-next]').addEventListener('click',()=>showImage(current+1));
function zoom(){const active=stage.classList.toggle('zoomed');viewer.querySelector('[data-zoom]').textContent=active?'Fit image':'Zoom in';viewer.querySelector('[data-zoom]').setAttribute('aria-pressed',String(active));stage.scrollTop=0;stage.scrollLeft=0}viewer.querySelector('[data-zoom]').addEventListener('click',zoom);viewImage.addEventListener('click',zoom);viewer.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();showImage(current+1)}if(event.key==='ArrowLeft'){event.preventDefault();showImage(current-1)}});

// Project correspondence: compose, review, then open an unsent email draft.
const brief=document.querySelector('#brief-dialog');const form=document.querySelector('#brief-form');const review=document.querySelector('#brief-review');let briefText='';
document.querySelectorAll('.brief-open').forEach(b=>b.addEventListener('click',()=>{form.hidden=false;review.hidden=true;open(brief,b)}));
const goal=document.querySelector('#brief-goal');goal.addEventListener('input',()=>goal.setCustomValidity(''));
form.addEventListener('submit',event=>{event.preventDefault();if(!goal.value.trim()){goal.setCustomValidity('Please describe the project.');goal.reportValidity();return}const values=new FormData(form);briefText=`Hi Rifaldy,\n\nI’d like to discuss a project.\n\nArea: ${values.get('service')}\nBrief: ${values.get('goal').trim()}\nTiming: ${values.get('timing')}\n\nLet’s discuss the next steps.`;review.querySelector('.brief-preview').textContent=briefText;document.querySelector('#brief-email').href=`mailto:rifaldiriqhia@gmail.com?subject=${encodeURIComponent('Project inquiry / '+values.get('service'))}&body=${encodeURIComponent(briefText)}`;form.hidden=true;review.hidden=false;document.querySelector('#brief-email').focus()});
document.querySelector('#brief-edit').addEventListener('click',()=>{form.hidden=false;review.hidden=true;goal.focus()});document.querySelector('#brief-copy').addEventListener('click',()=>copy(briefText,'Project note copied.'));
let scrollQueued=false;
function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.transform=`scaleX(${max>0?scrollY/max:0})`;scrollQueued=false}
addEventListener('scroll',()=>{if(!scrollQueued){requestAnimationFrame(progress);scrollQueued=true}},{passive:true});addEventListener('resize',progress);progress();
if('IntersectionObserver' in window){const indexObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;document.querySelectorAll('.site-index nav a').forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('#work,#experience,#practice,#archive,#contact').forEach(s=>indexObserver.observe(s))}
// Bring focus to the destination when following an in-page anchor with a keyboard.
